import re

def extract_code(reply: str) -> str:
    """从模型回答里提取纯 Python 代码。
    优先提取 ```python ... ``` 代码块；没有代码块则从首个 def/from/import
    开头的行开始截取到结尾；都没有则返回原文。
    """
    # 优先提取 ```python ... ``` 代码块
    match = re.search(r"```python[ \t]*\r?\n(.*?)```", reply, re.DOTALL)
    if match:
        return match.group(1).strip()

    # 没有代码块：从首个 def/from/import 开头的行开始截取到结尾
    lines = reply.splitlines(keepends=True)
    for idx, line in enumerate(lines):
        stripped = line.lstrip()
        if re.match(r"(?:def|from|import)\b", stripped):
            return "".join(lines[idx:]).strip()

    # 都没有则返回原文
    return reply

